
import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { FileSearch, CheckCircle, AlertCircle, BookOpenText } from 'lucide-react';
import { cn } from '@/lib/utils';

interface CVAnalysisProps {
  data: any;
  className?: string;
}

const CVDeepAnalysis: React.FC<CVAnalysisProps> = ({ data, className }) => {
  // Sample analysis data - in a real app, this would be generated by AI
  const analysisSections = [
    {
      name: "Technical Skills",
      items: data.skills.map((skill: any) => ({
        item: skill.name,
        strength: skill.proficiency >= 80 ? "Strong" : skill.proficiency >= 60 ? "Moderate" : "Developing",
        recommendation: skill.proficiency >= 80 
          ? "Highlight this as a core competency" 
          : "Consider additional projects to strengthen this skill"
      }))
    },
    {
      name: "Career Progression",
      items: [
        {
          item: "Role Advancement",
          strength: "Strong",
          recommendation: "Clear progression from Junior to Senior roles"
        },
        {
          item: "Industry Experience",
          strength: "Moderate",
          recommendation: "Consider diversifying industry exposure"
        }
      ]
    },
    {
      name: "Content Analysis",
      items: [
        {
          item: "Action Verbs",
          strength: "Strong",
          recommendation: "Effective use of action-oriented language"
        },
        {
          item: "Quantifiable Achievements",
          strength: "Moderate",
          recommendation: "Add more metrics and percentages to demonstrate impact"
        },
        {
          item: "Keyword Optimization",
          strength: "Strong",
          recommendation: "Well-optimized for ATS systems"
        }
      ]
    }
  ];

  const getStrengthBadge = (strength: string) => {
    switch (strength) {
      case "Strong":
        return <Badge variant="purple" className="font-medium">Strong</Badge>;
      case "Moderate":
        return <Badge variant="outline" className="bg-blue-50 text-blue-700 border-blue-200">Moderate</Badge>;
      default:
        return <Badge variant="outline" className="bg-orange-50 text-orange-700 border-orange-200">Developing</Badge>;
    }
  };

  return (
    <div className={cn("space-y-6", className)}>
      <div className="flex items-center space-x-3 mb-6">
        <div className="bg-purple-100 p-2 rounded-full">
          <FileSearch className="h-6 w-6 text-purple-600" />
        </div>
        <h2 className="text-2xl font-bold">In-Depth CV Analysis</h2>
      </div>

      <Card className="shadow-md border-purple-100">
        <CardHeader className="bg-purple-50 border-b border-purple-100">
          <CardTitle className="text-lg flex items-center gap-2">
            <BookOpenText className="h-5 w-5 text-purple-600" />
            Executive Summary
          </CardTitle>
        </CardHeader>
        <CardContent className="pt-6">
          <div className="space-y-4">
            <p className="text-gray-700">
              Your CV demonstrates a <span className="font-medium text-purple-700">strong technical foundation</span> with 
              clear progression in your career. The content is well-structured and highlights your achievements effectively.
            </p>
            
            <div className="flex flex-wrap gap-3 mt-2">
              <div className="flex items-center gap-1.5 bg-green-50 text-green-700 px-3 py-1.5 rounded-full text-sm">
                <CheckCircle className="h-4 w-4" />
                <span>ATS Friendly</span>
              </div>
              <div className="flex items-center gap-1.5 bg-green-50 text-green-700 px-3 py-1.5 rounded-full text-sm">
                <CheckCircle className="h-4 w-4" />
                <span>Clear Progression</span>
              </div>
              <div className="flex items-center gap-1.5 bg-yellow-50 text-yellow-700 px-3 py-1.5 rounded-full text-sm">
                <AlertCircle className="h-4 w-4" />
                <span>Add Metrics</span>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {analysisSections.map((section, index) => (
        <Card key={index} className="shadow-sm">
          <CardHeader className="py-4 px-6">
            <CardTitle className="text-lg">{section.name}</CardTitle>
          </CardHeader>
          <CardContent className="px-0">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-[40%]">Item</TableHead>
                  <TableHead className="w-[20%]">Strength</TableHead>
                  <TableHead className="w-[40%]">Recommendation</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {section.items.map((item, itemIndex) => (
                  <TableRow key={itemIndex}>
                    <TableCell className="font-medium">{item.item}</TableCell>
                    <TableCell>{getStrengthBadge(item.strength)}</TableCell>
                    <TableCell className="text-sm text-gray-600">{item.recommendation}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      ))}
    </div>
  );
};

export default CVDeepAnalysis;
